import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

reduce_mean_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <vector>

__global__ void reduce_mean_3d_dim0_kernel(const float* input, float* output, int size0, int size1, int size2) {
    int index = blockIdx.x * blockDim.x + threadIdx.x;
    int total = size1 * size2;
    if (index < total) {
        int i = index / size2;
        int j = index % size2;
        float sum = 0.0f;
        for (int b = 0; b < size0; b++) {
            sum += input[b * size1 * size2 + i * size2 + j];
        }
        output[index] = sum / size0;
    }
}

__global__ void reduce_mean_3d_dim1_kernel(const float* input, float* output, int size0, int size1, int size2) {
    int index = blockIdx.x * blockDim.x + threadIdx.x;
    int total = size0 * size2;
    if (index < total) {
        int i = index / size2;
        int j = index % size2;
        float sum = 0.0f;
        for (int b = 0; b < size1; b++) {
            sum += input[i * size1 * size2 + b * size2 + j];
        }
        output[index] = sum / size1;
    }
}

__global__ void reduce_mean_3d_dim2_kernel(const float* input, float* output, int size0, int size1, int size2) {
    int index = blockIdx.x * blockDim.x + threadIdx.x;
    int total = size0 * size1;
    if (index < total) {
        int i = index / size1;
        int j = index % size1;
        float sum = 0.0f;
        for (int b = 0; b < size2; b++) {
            sum += input[i * size1 * size2 + j * size2 + b];
        }
        output[index] = sum / size2;
    }
}

torch::Tensor reduce_mean_cuda(torch::Tensor x, int dim) {
    auto sizes = x.sizes();
    TORCH_CHECK(x.dim() == 3, "This custom kernel only supports 3D tensors.");
    int size0 = sizes[0];
    int size1 = sizes[1];
    int size2 = sizes[2];

    const int block_size = 256;
    torch::Tensor out;

    if (dim == 0) {
        out = torch::zeros({size1, size2}, x.options());
        int total = size1 * size2;
        int grid_size = (total + block_size - 1) / block_size;
        reduce_mean_3d_dim0_kernel<<<grid_size, block_size>>>(
            x.data_ptr<float>(), out.data_ptr<float>(), size0, size1, size2
        );
    } else if (dim == 1) {
        out = torch::zeros({size0, size2}, x.options());
        int total = size0 * size2;
        int grid_size = (total + block_size - 1) / block_size;
        reduce_mean_3d_dim1_kernel<<<grid_size, block_size>>>(
            x.data_ptr<float>(), out.data_ptr<float>(), size0, size1, size2
        );
    } else if (dim == 2) {
        out = torch::zeros({size0, size1}, x.options());
        int total = size0 * size1;
        int grid_size = (total + block_size - 1) / block_size;
        reduce_mean_3d_dim2_kernel<<<grid_size, block_size>>>(
            x.data_ptr<float>(), out.data_ptr<float>(), size0, size1, size2
        );
    } else {
        TORCH_CHECK(false, "Dimension must be 0, 1, or 2 for this custom kernel.");
    }
    return out;
}
"""

reduce_mean_cpp_source = r"""
torch::Tensor reduce_mean_cuda(torch::Tensor x, int dim);
"""

reduce_mean = load_inline(
    name="reduce_mean",
    cpp_sources=reduce_mean_cpp_source,
    cuda_sources=reduce_mean_source,
    functions=["reduce_mean_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(self, dim: int):
        super().__init__()
        self.dim = dim
        self.reduce_mean = reduce_mean

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.reduce_mean.reduce_mean_cuda(x, self.dim)
